mapper.sql:
WHERE (
    (
        r.TARGET_TYPE = 'feed'
        AND EXISTS (
            SELECT 1
            FROM FEED f
            WHERE f.CODE = r.TARGET_CODE
              AND f.MEM_CODE = #{memberCode}
        )
    )
    OR
    (
        r.TARGET_TYPE = 'comment'
        AND EXISTS (
            SELECT 1
            FROM COMMENTS c
            WHERE c.CODE = r.TARGET_CODE
              AND c.MEM_CODE = #{memberCode}
        )
    )
    OR
    (
        r.TARGET_TYPE = 'market'
        AND EXISTS (
            SELECT 1
            FROM MARKET_PRODUCT p
            WHERE p.CODE = r.TARGET_CODE
              AND p.MEM_CODE = #{memberCode}
        )
    )
)

mapper.select:
SELECT r.CODE, r.MEM_CODE, r.TARGET_TYPE, r.TARGET_CODE, r.REASON_TYPE, r.CONTENT, r.STATUS, r.CREATED_AT
FROM REPORT r
ORDER BY r.CREATED_AT DESC, r.CODE DESC LIMIT #{perPage} OFFSET #{offset}
